from build_common import *
from build_work import fig, vl, chips, sec

est = t("My estimate","Mon estimation")
head = cs_header(
  [t("European EdTech platform","Plateforme EdTech européenne"), "2021 – 2025", t("Employee, then migration lead","Salarié, puis responsable de la migration")],
  t("Four years building the integration platform that keeps client data flowing into an EdTech product","Quatre ans à construire la plateforme d'intégration qui alimente un produit EdTech avec les données de ses clients"),
  t("At a European learning platform, every client's HR and training systems had to stay in sync with the product. I worked on that problem through three generations of the platform: from per-client scripts, to a configuration-driven engine, to a multi-tenant Airflow platform on AWS that I took over and brought to production. A year after I left, it still runs every night.",
    "Dans une plateforme e-learning européenne, les systèmes RH et formation de chaque client devaient rester synchronisés avec le produit. J'ai travaillé sur ce problème à travers trois générations de la plateforme : des scripts par client, puis un moteur piloté par configuration, puis une plateforme Airflow multi-clients sur AWS, que j'ai reprise et menée jusqu'à la production. Un an après mon départ, elle tourne toujours chaque nuit."),
  '<div class="figures" role="list">'
  + fig("~220", t("client data flows migrated from Celery to Airflow on AWS MWAA, 153 of them active when I left","flux de données clients migrés de Celery vers Airflow sur AWS MWAA, dont 153 actifs à mon départ"))
  + fig("3 d <small>→</small> ½ d", t("typical work to onboard a new client: custom scripting became configuration","de travail pour intégrer un nouveau client : le développement sur mesure est devenu de la configuration"), est)
  + fig("30+ <small>→</small> &lt;2 <small>min</small>", t("to find and read a failed task's log, after I brought MWAA logs into Datadog","pour trouver et lire le log d'une tâche en échec, après l'intégration des logs MWAA dans Datadog"), est)
  + fig("~45%", t("fewer fix commits per month after the cut-over to Airflow","de commits de correction en moins par mois après le passage à Airflow"))
  + fig("100%", t("of DAGs alert on failure, so the team usually knew about a problem before the client did","des DAG alertent en cas d'échec : l'équipe était généralement au courant avant le client"))
  + fig("98.6%", t("task success a year later, across ~1,400 task runs a day for 93 client companies","de tâches réussies un an plus tard, sur ~1 400 exécutions par jour pour 93 entreprises clientes"))
  + '</div><p class="note">' + t("Flow, schedule and commit figures come from the codebase, its git history and production exports. “Fix commits” compares six months before and five months after the cut-over; a fix commit is a proxy, not an incident count. The onboarding and debugging times are my own estimates. The 98.6% figure is from a 14-day production window in November 2026, a year after I left: it describes the platform as the team runs it today.",
     "Les chiffres de flux, de planification et de commits viennent du code, de son historique git et d'exports de production. Les « commits de correction » comparent six mois avant et cinq mois après la bascule ; c'est un indicateur, pas un nombre d'incidents. Les durées d'intégration et de débogage sont mes estimations. Le chiffre de 98,6 % provient d'une fenêtre de production de 14 jours en novembre 2026, un an après mon départ : il décrit la plateforme telle que l'équipe l'exploite aujourd'hui.") + "</p>")

body = head
body += sec("problem", t("The business problem","Le problème"), t("Every client sends its data differently, and the product has to stay correct anyway","Chaque client envoie ses données à sa façon, et le produit doit rester juste malgré tout"),
  "<p>" + t("Each client company had its own HR or training system: SFTP drops of encrypted CSV files, REST APIs, or enterprise HR suites. Users, groups, courses, sessions and enrollments had to arrive in the product on schedule, with each client's own rules for who is active, what can be overwritten, and what happens to people who leave. A wrong sync means employees who can't log in, missing training records, or compliance gaps.",
            "Chaque entreprise cliente avait son propre système RH ou formation : dépôts SFTP de fichiers CSV chiffrés, API REST ou suites RH d'entreprise. Utilisateurs, groupes, formations, sessions et inscriptions devaient arriver dans le produit à l'heure, avec les règles propres à chaque client : qui est actif, ce qui peut être écrasé, ce qui arrive aux personnes qui partent. Une synchronisation ratée, ce sont des salariés qui ne peuvent pas se connecter, des historiques de formation manquants ou des écarts de conformité.") + "</p>")

def stage(cls, when, h3, lis, role):
    return f'<div class="stage {cls}"><div class="rail"><span class="dot" aria-hidden="true"></span><span class="bar" aria-hidden="true"></span></div><span class="when">{when}</span><h3>{h3}</h3><ul>' + "".join(f"<li>{l}</li>" for l in lis) + f'</ul><p class="role">{role}</p></div>'

body += sec("journey", t("What I built","Ce que j'ai construit"), t("Three generations of the platform, and my part in each","Trois générations de la plateforme, et mon rôle dans chacune"),
  '<div class="track">'
  + stage("", t("2021 – 2025 · legacy","2021 – 2025 · historique"), t("Per-client connectors","Connecteurs par client"),
      [t("One script per client, run by cron on a single server: about 25 connectors and 118 client configurations","Un script par client, lancé par cron sur un seul serveur : environ 25 connecteurs et 118 configurations clients"), t("Fast to start, but duplicated code and no isolation","Rapide à démarrer, mais du code dupliqué et aucune isolation")],
      t("Ran the cron server and owned connectors end to end: client spec meetings, development, pre-production testing, release, monitoring and support tickets. Built new ones, including an SAP SuccessFactors integration, and maintained the rest.","J'exploitais le serveur cron et je gérais les connecteurs de bout en bout : réunions de spécification client, développement, tests en préproduction, mise en production, supervision et tickets de support. J'en ai créé de nouveaux, dont une intégration SAP SuccessFactors, et maintenu les autres."))
  + stage("", "2022 – 2025 · Celery on AWS ECS".replace("on","on"), t("A configuration-driven engine","Un moteur piloté par configuration"),
      [t("Flows defined in a back office instead of written in code","Des flux définis dans un back-office au lieu d'être codés"), t("A layered ETL engine with lifecycle hooks, run by Celery workers","Un moteur ETL en couches avec des hooks de cycle de vie, exécuté par des workers Celery")],
      t("One of the two main developers, with 559 commits: client flows, hooks and the shared engine.","L'un des deux principaux développeurs, avec 559 commits : flux clients, hooks et moteur commun."))
  + stage("now", "2024 – 2025 · Airflow · AWS MWAA", t("A multi-tenant orchestration platform","Une plateforme d'orchestration multi-clients"),
      [t("One DAG generated per client flow: ~220 flows migrated, 153 active, 14 tasks per DAG","Un DAG généré par flux client : ~220 flux migrés, 153 actifs, 14 tâches par DAG"), t("Dependent flows trigger each other's DAGs in business order","Les flux dépendants se déclenchent dans l'ordre métier"), t("Per-step tasks, retries, alerts and lossless hand-offs between steps","Des tâches par étape, des relances, des alertes et des passages de relais sans perte entre étapes")],
      t("Took the migration over when its architect left. Built it largely alone for six months, then led a team of three through to the production switch in April 2025.","J'ai repris la migration au départ de son architecte. Je l'ai construite en grande partie seul pendant six mois, puis j'ai mené une équipe de trois personnes jusqu'à la mise en production en avril 2025."))
  + "</div>")

body += sec("later", t("A year later","Un an plus tard"), t("The platform still runs in production, maintained by the team","La plateforme tourne toujours en production, maintenue par l'équipe"),
  '<div class="cols"><div class="col"><p>' + t("I left in November 2025. In November 2026 the team ran production queries over a 14-day window. The platform had grown to a third cloud and kept the same design: one generated DAG per client flow, alerts on every DAG, logs searchable by DAG and task.","Je suis parti en novembre 2025. En novembre 2026, l'équipe a interrogé la production sur une fenêtre de 14 jours. La plateforme s'est étendue à un troisième cloud et garde la même conception : un DAG généré par flux client, des alertes sur chaque DAG, des logs consultables par DAG et par tâche.") + "</p>"
  + '<div class="kv"><div><b>111</b><span>' + t("active client flows","flux clients actifs") + '</span></div><div><b>93</b><span>' + t("client companies on 3 clouds","entreprises clientes sur 3 clouds") + '</span></div><div><b>~1,400</b><span>' + t("task runs a day","exécutions de tâches par jour") + '</span></div><div><b>98.6%</b><span>' + t("task success","de tâches réussies") + "</span></div></div></div>"
  + '<div class="col"><h3>' + t("Why DAG runs fail, over 1,606 runs","Pourquoi les exécutions échouent, sur 1 606 exécutions") + '</h3>'
  + '<div class="runbar" role="img" aria-label="1,391 / ~180 / ~35"><i style="width:86.6%;background:var(--accent)"></i><i style="width:11.2%;background:var(--signal)"></i><i style="width:2.2%;background:var(--ink)"></i></div>'
  + '<ul class="legend"><li><span class="sw" style="background:var(--accent)"></span><span>' + t("Succeeded","Réussies") + '</span><span class="n">1,391</span></li><li><span class="sw" style="background:var(--signal)"></span><span>' + t("No input: the client's file wasn't there","Pas de données : le fichier du client était absent") + '</span><span class="n">~180</span></li><li><span class="sw" style="background:var(--ink)"></span><span>' + t("Real task error","Vraie erreur de tâche") + '</span><span class="n">~35</span></li></ul>'
  + '<p class="note">' + t("About 98% of runs either succeed or stop because the client's file is missing. Counting a missing file as a failure is a design choice I'd revisit: a sensor or a soft skip would keep the failure rate honest.","Environ 98 % des exécutions réussissent ou s'arrêtent faute de fichier client. Compter un fichier absent comme un échec est un choix que je revisiterais : un sensor ou un saut « doux » rendrait le taux d'échec plus juste.") + "</p></div></div>")

body += sec("value", t("Value delivered","Valeur apportée"), t("What changed for the business, and under the hood","Ce qui a changé pour l'entreprise, et sous le capot"),
  '<div class="cols"><div class="col"><h3>' + t("For the business","Pour l'entreprise") + ' <span class="tag">' + t("outcomes","résultats") + "</span></h3>"
  + vl([(t("Faster onboarding","Intégration plus rapide"), t("From about 3 days of custom scripting to about half a day of configuration (my estimate). Most clients needed no client-specific code, customizations came from a library of 43 reusable hooks, and 73% of clients went live the day their flow was configured.","D'environ 3 jours de développement sur mesure à environ une demi-journée de configuration (mon estimation). La plupart des clients n'ont nécessité aucun code spécifique, les personnalisations venaient d'une bibliothèque de 43 hooks réutilisables, et 73 % des clients ont démarré le jour même de la configuration de leur flux.")),
        (t("Problems found first","Problèmes détectés en premier"), t("On the old system, clients or support usually reported a failed sync. With alerts on every DAG and a daily morning check, the team found failures first. Almost 9 in 10 syncs ran overnight, so most problems were fixed before the client's working day started.","Sur l'ancien système, c'étaient en général les clients ou le support qui signalaient une synchronisation ratée. Avec des alertes sur chaque DAG et un contrôle chaque matin, l'équipe détectait les échecs en premier. Près de 9 synchronisations sur 10 tournaient la nuit : la plupart des problèmes étaient réglés avant le début de la journée du client.")),
        (t("Fewer fixes","Moins de corrections"), t("Fix commits per month dropped about 45% after the move to Airflow, and Slack alerts link straight to the failing step.","Les commits de correction ont baissé d'environ 45 % par mois après le passage à Airflow, et les alertes Slack pointent directement vers l'étape en échec.")),
        (t("Continuity","Continuité"), t("The migration kept moving after its architect left the company, reached production in April 2025, and still runs a year after I left.","La migration a continué après le départ de son architecte, est passée en production en avril 2025, et tourne toujours un an après mon départ.")),
        (t("Client trust","Confiance client"), t("Every run emails the client a report of rejected rows and the reason for each, so clients can fix their own data.","Chaque exécution envoie au client un rapport des lignes rejetées et de la raison de chaque rejet, pour qu'il corrige lui-même ses données.")),
        (t("Compliance","Conformité"), t("Encrypted credentials and files, hashed passwords, and automatic anonymization of long-suspended users.","Identifiants et fichiers chiffrés, mots de passe hachés, et anonymisation automatique des utilisateurs suspendus depuis longtemps."))])
  + '</div><div class="col"><h3>' + t("Under the hood","Sous le capot") + ' <span class="tag">' + t("engineering","technique") + "</span></h3>"
  + vl([(t("Orchestration","Orchestration"), t("Dynamic DAG generation from database configs, task groups, branching, and flow-to-flow triggers that never cascade from a manual test run.","Génération dynamique de DAG à partir de configurations en base, groupes de tâches, branchements, et déclenchements entre flux qui ne se propagent jamais depuis un test manuel.")),
        (t("Observability","Observabilité"), t("A Lambda forwarder ships MWAA's CloudWatch logs to Datadog, and a Datadog log pipeline parses them so you can filter by DAG and task. Airflow's own logging stays untouched.","Une Lambda transfère les logs CloudWatch de MWAA vers Datadog, où un pipeline de logs les analyse pour filtrer par DAG et par tâche. La journalisation d'Airflow reste intacte.")),
        (t("Data integrity","Intégrité des données"), t("Idempotent upserts on business keys, snapshot comparison to deactivate missing records, soft deletes, and a user-lifecycle state machine.","Upserts idempotents sur clés métier, comparaison de snapshots pour désactiver les enregistrements disparus, suppressions logiques, et machine à états pour le cycle de vie des utilisateurs.")),
        (t("Type safety","Typage"), t("A schema saved next to each intermediate file, so integers, booleans, dates and nulls survive every hand-off between tasks.","Un schéma enregistré à côté de chaque fichier intermédiaire, pour que entiers, booléens, dates et valeurs nulles survivent à chaque passage entre tâches.")),
        (t("Performance","Performance"), t("Line-by-line memory and CPU profiling on MWAA, then paginated loading to fix worker memory exhaustion.","Profilage mémoire et CPU ligne par ligne sur MWAA, puis chargement paginé pour corriger l'épuisement mémoire des workers.")),
        (t("Delivery","Livraison"), t("Versioned DAG deploys on S3 with one-step rollback, a Makefile for one-command local setup and the test database, and pre-commit checks (Black, Flake8, MyPy).","Déploiements de DAG versionnés sur S3 avec retour arrière en une étape, un Makefile pour installer l'environnement local et la base de test en une commande, et des contrôles pre-commit (Black, Flake8, MyPy)."))])
  + "</div></div>")

def card(k, h3, p, out):
    return f'<article class="card"><span class="k">{k}</span><h3>{h3}</h3><p>{p}</p><p class="out">{out}</p></article>'
body += sec("highlights", t("Highlights","Points forts"), t("Pieces of work I can walk you through","Des réalisations que je peux vous détailler"),
  '<div class="grid">'
  + card(t("Ownership","Prise en main"), t("Took over the Airflow migration","Reprise de la migration Airflow"), t("When the colleague who proposed the move to Airflow left, I turned his proposal into a working platform and designed its core logic.","Quand le collègue à l'origine du passage à Airflow est parti, j'ai transformé sa proposition en plateforme opérationnelle et conçu sa logique centrale."), t("Production switch in April 2025; the platform's largest contributor, with about half of all commits.","Mise en production en avril 2025 ; principal contributeur de la plateforme, avec environ la moitié des commits."))
  + card(t("Architecture","Architecture"), t("One DAG per client flow","Un DAG par flux client"), t("A generator reads flows and schedules from each cloud's database and builds a tagged, scheduled DAG for every client flow, chained in business order.","Un générateur lit les flux et plannings dans la base de chaque cloud et construit un DAG planifié et étiqueté pour chaque flux client, enchaîné dans l'ordre métier."), t("Onboarding a flow means configuring it, not deploying code.","Intégrer un flux, c'est le configurer, pas déployer du code."))
  + card(t("Refactor","Refonte"), t("From one big task to per-step tasks","D'une grosse tâche à des tâches par étape"), t("I split the old single-process run into extract, transform, load and hook tasks that pass data through object storage and only references through Airflow.","J'ai découpé l'ancienne exécution monolithique en tâches d'extraction, de transformation, de chargement et de hooks qui font transiter les données par le stockage objet et seulement des références par Airflow."), t("Re-run from the failed step, with timing and logs for each step.","Relance depuis l'étape en échec, avec durée et logs pour chaque étape."))
  + card(t("Diagnosis","Diagnostic"), t("Memory exhaustion on MWAA","Épuisement mémoire sur MWAA"), t("Profiling showed one ORM call adding about 220 MiB per 10,000 rows; I rewrote it as a paginated generator.","Le profilage a montré qu'un appel ORM ajoutait environ 220 Mio par tranche de 10 000 lignes ; je l'ai réécrit en générateur paginé."), t("A measured fix, plus a lesson about the memory-versus-CPU trade-off.","Une correction mesurée, et une leçon sur l'arbitrage mémoire/CPU."))
  + card(t("Delivery","Livraison"), t("Safe deploys and developer tooling","Déploiements sûrs et outillage"), t("Each CI pipeline uploads the DAGs to its own versioned S3 path, so a deploy is atomic and a rollback is one step. I also created the repo's Makefile and its first pre-commit hooks.","Chaque pipeline CI publie les DAG dans un chemin S3 versionné : un déploiement est atomique et un retour arrière se fait en une étape. J'ai aussi créé le Makefile du dépôt et ses premiers hooks pre-commit."), t("New engineers set up in one command.","Un nouvel ingénieur s'installe en une commande."))
  + card(t("AI integration","Intégration IA"), t("An MCP server for client data","Un serveur MCP pour les données clients"), t("Designed and deployed a Model Context Protocol server on AWS Lambda so clients could query their training data from AI assistants, with tenant isolation, OAuth and rate limiting.","Conception et déploiement d'un serveur Model Context Protocol sur AWS Lambda pour que les clients interrogent leurs données de formation depuis des assistants IA, avec isolation par client, OAuth et limitation de débit."), t("An open-source re-implementation is on GitHub.","Une réimplémentation open source est sur GitHub."))
  + '<article class="card wide"><div class="body"><span class="k">' + t("Observability","Observabilité") + '</span><h3>' + t("Getting MWAA's logs into Datadog without fighting the platform","Amener les logs MWAA dans Datadog sans lutter contre la plateforme") + "</h3><p>"
  + t("On MWAA, task logs lived only in CloudWatch, and you couldn't search them by DAG or task. I tested four ways to fix it inside Airflow: S3 remote logging, a custom log format, a custom formatter plugin and JSON logs. MWAA's locked logging blocked all four. So I moved the fix downstream: a Datadog Forwarder Lambda subscribes to MWAA's CloudWatch log groups, and a Datadog log pipeline parses each line into DAG, task and other attributes.",
      "Sur MWAA, les logs des tâches n'existaient que dans CloudWatch, sans recherche possible par DAG ou par tâche. J'ai testé quatre solutions dans Airflow : journalisation distante S3, format de log personnalisé, plugin de formatage et logs JSON. La journalisation verrouillée de MWAA a bloqué les quatre. J'ai donc déplacé la solution en aval : une Lambda Datadog Forwarder s'abonne aux groupes de logs CloudWatch de MWAA, et un pipeline de logs Datadog découpe chaque ligne en DAG, tâche et autres attributs.")
  + '</p></div><div class="ba"><div class="before"><b>30+ min</b><span>' + t("before: digging through CloudWatch log streams","avant : fouiller les flux de logs CloudWatch") + '</span></div><div><b>&lt; 2 min</b><span>' + t("after: filter by DAG and task in Datadog (my estimate)","après : filtrer par DAG et par tâche dans Datadog (mon estimation)") + "</span></div></div></article>"
  + "</div>")

body += sec("order", t("How a client's data moves","Comment circulent les données d'un client"), t("A client's DAGs trigger each other in business order","Les DAG d'un client se déclenchent dans l'ordre métier"),
  '<div class="chain">' + '<span class="a">→</span>'.join(f'<span class="n">{x}</span>' for x in ["users","categories","trainings","sessions","subscriptions"]) + "</div>")
body += sec("tools", t("Toolbox","Outils"), t("What I used every day","Ce que j'utilisais au quotidien"),
  chips([(t("Orchestration &amp; pipelines","Orchestration &amp; pipelines"), ["Apache Airflow","AWS MWAA","Celery",t("ETL design","Conception ETL"),t("Dynamic DAGs","DAG dynamiques")]),
         (t("Languages &amp; data","Langages &amp; données"), ["Python","SQL","pandas","SQLAlchemy","MySQL"]),
         ("Cloud", ["S3","ECS / Fargate","Lambda","RDS","Transfer Family","CloudWatch"]),
         (t("Reliability &amp; delivery","Fiabilité &amp; livraison"), ["Datadog",t("Slack alerting","Alertes Slack"),"pytest","pre-commit","Black · Flake8 · MyPy","Make","GitLab CI","Docker"])]))
body += cs_cta()
open("site/work/integration-platform.html","w").write(page("Integration Platform · Case Study","Plateforme d'intégration · Étude de cas","Four years building a multi-tenant integration platform for a European EdTech product, ending with ~220 client flows on Apache Airflow (AWS MWAA).", body, root="../"))
